#!/usr/bin/env python3
"""
Regenerate sub-section landing pages as card-grid summaries.

Walks every `docs/**/index.md` that still carries the
"auto-generated by `scripts/gen-frontmatter-and-index.py`" marker and
rewrites it into a useful landing page:

  - Each child markdown file gets a card (icon + title + first meaningful
    sentence pulled from the doc, with a "Reviewed YYYY-MM-DD" footer).
  - Each child subdirectory gets a card linking to its own index.md, with
    the count of descendants in the footer.
  - Frontmatter is preserved; `search.exclude: true` is removed because
    these regenerated landings are real navigation now.

The script is idempotent — running it again on a landing that was just
regenerated leaves it alone (no marker to re-process).

Curated indexes that have been hand-edited are skipped automatically:
removing the auto-gen marker is the opt-out signal.

Run:
    python3 scripts/regen-section-landings.py
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"

MARKER = "auto-generated by `scripts/gen-frontmatter-and-index.py`"

# Folder-name → (display name, icon) for the common service / doc-type folders.
# Falls back to a generic icon for anything unmatched.
TYPE_ICON_MAP: dict[str, tuple[str, str]] = {
    "sop":                       ("SOPs", "material-clipboard-check-outline"),
    "sops":                      ("SOPs", "material-clipboard-check-outline"),
    "troubleshooting":           ("Troubleshooting", "material-fire-alert"),
    "capacity":                  ("Capacity", "material-gauge"),
    "migration":                 ("Migration", "material-truck-fast-outline"),
    "version-upgrade":           ("Version upgrades", "material-arrow-up-bold-circle-outline"),
    "disaster-recovery":         ("Disaster recovery", "material-shield-alert-outline"),
    "deep-dives":                ("Deep dives", "material-book-open-variant"),
    "development":               ("Development", "material-code-braces"),
    "production":                ("Production", "material-server"),
    "staging":                   ("Staging", "material-test-tube"),
    "design-decisions":          ("Design decisions", "material-file-tree-outline"),
    "comparisons":               ("Comparisons", "material-compare-horizontal"),
    "analytics":                 ("Analytics", "material-chart-line"),
    "agentic-gateway":           ("Agentic gateway", "material-gateway"),
    "s3-filesystem-efs-csi-driver":
                                 ("S3 / EFS CSI driver", "material-database-cog-outline"),
    # Service folders — use service icon
    "eks":                       ("EKS", "material-kubernetes"),
    "msk":                       ("MSK (Kafka)", "material-message-bulleted"),
    "elasticache":               ("ElastiCache (Redis)", "material-memory"),
    "documentdb":                ("DocumentDB (MongoDB)", "material-database-outline"),
    "opensearch":                ("OpenSearch", "material-magnify"),
    "rds":                       ("RDS", "material-database"),
    "ses":                       ("SES (Email)", "material-email-outline"),
    "argocd":                    ("Argo CD", "material-sync"),
    "waf":                       ("WAF", "material-shield-outline"),
    "vpc":                       ("VPC / networking", "material-router-network"),
    "iam":                       ("IAM", "material-key-outline"),
    "mcd":                       ("MCD", "material-router-network"),
    "github":                    ("GitHub", "material-github"),
    "aws":                       ("AWS", "material-cloud-outline"),
    "security":                  ("Security", "material-shield-lock-outline"),
    "wiz":                       ("Wiz findings", "material-shield-search"),
    "operations":                ("Operations", "material-tools"),
    "process":                   ("Process", "material-clipboard-list-outline"),
    "identity":                  ("Identity", "material-account-circle-outline"),
    "infrastructure":            ("Infrastructure", "material-server-network"),
    "pipelines":                 ("Pipelines", "material-pipe"),
    "cluster-lifecycle":         ("Cluster lifecycle", "material-recycle"),
}

DEFAULT_FILE_ICON = "material-file-document-outline"
DEFAULT_FOLDER_ICON = "material-folder-outline"


def _read_text(p: Path) -> str:
    try:
        return p.read_text(encoding="utf-8")
    except OSError:
        return ""


def _split_frontmatter(text: str) -> tuple[str, str, str]:
    if not text.startswith("---"):
        return "", "", text
    m = re.match(r"^(---\s*\n)(.*?\n)(---\s*\n)", text, flags=re.DOTALL)
    if not m:
        return "", "", text
    return m.group(1), m.group(2), text[m.end():]


def _extract_h1(text: str) -> str | None:
    body = _split_frontmatter(text)[2]
    # Skip leading <!-- … --> comments and blank lines
    body = re.sub(r"^(?:<!--.*?-->\s*\n|\s*\n)+", "", body, flags=re.DOTALL)
    m = re.match(r"^#\s+(.+?)\s*$", body, flags=re.MULTILINE)
    return m.group(1).strip() if m else None


def _extract_first_sentence(text: str) -> str | None:
    body = _split_frontmatter(text)[2]
    body = re.sub(r"<!--.*?-->", "", body, flags=re.DOTALL)
    # Strip fenced code blocks so we don't pull example YAML / shell as prose
    body = re.sub(r"```.*?```", "", body, flags=re.DOTALL)
    body = re.sub(r"^#\s+.*?\n+", "", body, flags=re.MULTILINE | re.DOTALL)
    # Split paragraphs on blank lines AND treat heading lines as boundaries
    # so that "## heading\nprose..." becomes two paragraphs.
    body = re.sub(r"(?m)^(#{1,6}\s+.+)$", r"\n\1\n", body)
    paragraphs = re.split(r"\n\s*\n", body, maxsplit=40)

    # Patterns we'd love to find first — pull the descriptive bit out.
    INTRO_RE = re.compile(
        r"\*\*(?:Objective|Purpose|Summary|Overview|Description|Goal|Context|Applies\s+to)[^*]*\*\*[:\s]*(.+)",
        re.IGNORECASE | re.DOTALL,
    )

    def _is_prose(para: str) -> bool:
        first = para.lstrip()
        if not first:
            return False
        if re.match(r"^(```|----+|---\s*$|- |\* |\| |> |!!!|#|<|\d+\.\s|=+\s*$|\s*\||//|/\*)", first):
            return False
        if first.startswith(("**Category:**", "**Applies To:**", "**Type:**", "**Owner:**", "**Service:**")):
            return False
        # Reject "lines that are mostly code" — pipes, backticks, semicolons
        if first.count("`") >= 3 or first.count("|") >= 3:
            return False
        return True

    def _format(para: str, limit: int = 180) -> str:
        text_only = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", para)
        text_only = re.sub(r"[*_`]", "", text_only)
        text_only = re.sub(r"^\s*-+\s*\n", "", text_only)
        text_only = " ".join(text_only.split())
        m = re.search(r"^(.{60," + str(limit) + r"}?[.!?])(?:\s|$)", text_only)
        if m:
            return m.group(1).strip()
        # No sentence boundary in range — truncate at the last whole word
        truncated = text_only[:limit].rstrip()
        if len(text_only) > limit:
            last_space = truncated.rfind(" ")
            if last_space > 40:
                truncated = truncated[:last_space] + "…"
        return truncated.strip()

    # Pass 1: an explicit "Objective / Purpose / Summary" intro
    for para in paragraphs:
        m = INTRO_RE.search(para)
        if m:
            snippet = _format(m.group(1))
            if len(snippet) >= 40:
                return snippet
    # Pass 2: first prose paragraph
    for para in paragraphs:
        if _is_prose(para):
            snippet = _format(para)
            if len(snippet) >= 40:
                return snippet
    return None


def _frontmatter_field(fm_body: str, key: str) -> str | None:
    m = re.search(rf"^{re.escape(key)}:\s*(.+?)\s*$", fm_body, flags=re.MULTILINE)
    if not m:
        return None
    return m.group(1).strip().strip("\"'")


def _humanize(name: str) -> str:
    if name in TYPE_ICON_MAP:
        return TYPE_ICON_MAP[name][0]
    return name.replace("-", " ").replace("_", " ").title()


def _icon_for(name: str, is_dir: bool) -> str:
    if name in TYPE_ICON_MAP:
        return TYPE_ICON_MAP[name][1]
    return DEFAULT_FOLDER_ICON if is_dir else DEFAULT_FILE_ICON


def _count_descendants(folder: Path) -> int:
    return sum(1 for _ in folder.rglob("*.md")) - 1  # exclude folder's own index.md


def _card_for_file(md: Path) -> str | None:
    text = _read_text(md)
    if not text:
        return None
    title = _extract_h1(text) or _humanize(md.stem)
    snippet = _extract_first_sentence(text) or "Open this doc for details."
    _, fm_body, _ = _split_frontmatter(text)
    reviewed = _frontmatter_field(fm_body, "last_reviewed") or ""
    doc_type = (_frontmatter_field(fm_body, "type") or "reference").lower()
    icon = TYPE_ICON_MAP.get(doc_type, ("", DEFAULT_FILE_ICON))[1]
    if doc_type in TYPE_ICON_MAP and not TYPE_ICON_MAP[doc_type][1]:
        icon = DEFAULT_FILE_ICON
    footer = f"    _Reviewed {reviewed}_\n\n" if reviewed else ""
    return (
        f"-   :{icon}:{{ .lg .middle }} __{title}__\n\n"
        f"    ---\n\n"
        f"    {snippet}\n\n"
        f"    [:octicons-arrow-right-24: Open]({md.name})\n\n"
        f"{footer}"
    )


def _card_for_folder(folder: Path) -> str | None:
    sub_index = folder / "index.md"
    text = _read_text(sub_index)
    title = _extract_h1(text) if text else None
    if not title:
        title = _humanize(folder.name)
    n = _count_descendants(folder)
    icon = _icon_for(folder.name, is_dir=True)
    descendants_text = f"{n} doc{'s' if n != 1 else ''}" if n > 0 else "Empty (placeholder)"
    summary = (
        _extract_first_sentence(text) if text and MARKER not in text else None
    )
    summary = summary or f"Everything filed under `{folder.name}/`."
    return (
        f"-   :{icon}:{{ .lg .middle }} __{title}__\n\n"
        f"    ---\n\n"
        f"    {summary}\n\n"
        f"    [:octicons-arrow-right-24: {descendants_text}]({folder.name}/index.md)\n\n"
    )


def _render_landing(folder: Path, old_fm: str, old_fm_body: str) -> str:
    title = _frontmatter_field(old_fm_body, "title") or _humanize(folder.name)
    rel = folder.relative_to(DOCS)

    # Drop search.exclude — a real landing should be in search.
    fm_body = re.sub(
        r"^search:\s*\n  exclude:\s*true\s*\n",
        "",
        old_fm_body,
        flags=re.MULTILINE,
    )

    children_dirs = sorted(
        d for d in folder.iterdir()
        if d.is_dir() and not d.name.startswith(("_", "."))
        and not d.name == "assets"
        and (d / "index.md").exists()
    )
    children_files = sorted(
        f for f in folder.iterdir()
        if f.is_file() and f.suffix == ".md"
        and f.name not in {"index.md", "README.md"}
    )

    section_blurb = (
        f"Everything we have on `{rel}/`. Pick a doc to jump straight in, "
        "or open a sub-section for a curated landing of its own."
    )

    parts: list[str] = [
        old_fm,
        fm_body,
        "---\n\n",
        f"# {title}\n\n",
        f"{section_blurb}\n\n",
    ]

    if children_dirs:
        parts.append("## Sub-sections\n\n")
        parts.append('<div class="grid cards" markdown>\n\n')
        for d in children_dirs:
            card = _card_for_folder(d)
            if card:
                parts.append(card)
        parts.append("</div>\n\n")

    if children_files:
        parts.append("## Documents\n\n")
        parts.append('<div class="grid cards" markdown>\n\n')
        for f in children_files:
            card = _card_for_file(f)
            if card:
                parts.append(card)
        parts.append("</div>\n")

    if not children_dirs and not children_files:
        parts.append(
            "_This section has no published docs yet. Track the roadmap in the parent landing._\n"
        )

    return "".join(parts)


def main() -> int:
    rewritten = 0
    skipped = 0
    for index_md in DOCS.rglob("index.md"):
        text = _read_text(index_md)
        if MARKER not in text:
            skipped += 1
            continue
        # Don't touch the section-root indexes that already have curated
        # landings (those won't carry the marker, but be defensive).
        old_fm, old_fm_body, _body = _split_frontmatter(text)
        if not old_fm:
            print(f"  skipping (no frontmatter): {index_md.relative_to(DOCS)}", file=sys.stderr)
            continue
        new_text = _render_landing(index_md.parent, old_fm, old_fm_body)
        index_md.write_text(new_text, encoding="utf-8")
        rewritten += 1
        print(f"  rewrote: {index_md.relative_to(DOCS)}")

    print(f"\nRewrote {rewritten} landings; left {skipped} curated indexes alone.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
